def validate_topics():
    print(f"Validating FCPS topics: count = {len(FCPS_TOPICS)}")
    assert len(FCPS_TOPICS) == 100, f"Expected 100 FCPS topics, got {len(FCPS_TOPICS)}"
    for idx, item in enumerate(FCPS_TOPICS):
        title, subj, sys, hallmark, ref_lbl, ref_url = item
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} at FCPS #{idx+1}: {title}"
        assert sys in TAXONOMY_SYSTEMS, f"Invalid system {sys} at FCPS #{idx+1}: {title}"
        assert len(title) >= 10, f"Title too short at FCPS #{idx+1}"
        assert len(hallmark) >= 15, f"Hallmark too short at FCPS #{idx+1}"
        assert ref_url.startswith("https://"), f"Invalid ref_url at FCPS #{idx+1}"
    print("  -> All 100 FCPS topics PASSED validation!")

    print(f"Validating NLE topics: count = {len(NLE_TOPICS)}")
    assert len(NLE_TOPICS) == 100, f"Expected 100 NLE topics, got {len(NLE_TOPICS)}"
    for idx, item in enumerate(NLE_TOPICS):
        title, subj, sys, hallmark, ref_lbl, ref_url = item
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} at NLE #{idx+1}: {title}"
        assert sys in TAXONOMY_SYSTEMS, f"Invalid system {sys} at NLE #{idx+1}: {title}"
        assert len(title) >= 10, f"Title too short at NLE #{idx+1}"
        assert len(hallmark) >= 15, f"Hallmark too short at NLE #{idx+1}"
        assert ref_url.startswith("https://"), f"Invalid ref_url at NLE #{idx+1}"
    print("  -> All 100 NLE topics PASSED validation!")

def export_topics():
    out_file = os.path.join(os.path.dirname(__file__), "mega89_topics_a.py")
    with open(out_file, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 89 Part A topics (FCPS 100, NLE 100)\n\n")
        f.write("FCPS_TOPICS = " + json.dumps(FCPS_TOPICS, indent=2) + "\n\n")
        f.write("NLE_TOPICS = " + json.dumps(NLE_TOPICS, indent=2) + "\n")
    print(f"Successfully generated {out_file} with 200 topics!")

if __name__ == "__main__":
    validate_topics()
    export_topics()
